/**
 * @description       : Invocable Apex action invoked by the 6 PM Scheduled Flow
 *                      (Daily_Collection_Summary_Slack). Aggregates total, closed,
 *                      pending, and escalated Collection_Case__c records and posts
 *                      the summary to #daily-collection-summary via SlackNotificationService.
 * @group             : Collections Management
 */
public with sharing class DailyCollectionSummaryInvocable {

    public class SummaryOutput {
        @InvocableVariable(label='Total Cases')
        public Integer totalCases;

        @InvocableVariable(label='Closed Cases')
        public Integer closedCases;

        @InvocableVariable(label='Pending Cases')
        public Integer pendingCases;

        @InvocableVariable(label='Escalated Cases')
        public Integer escalatedCases;
    }

    @InvocableMethod(
        label='Calculate and Send Daily Collection Summary'
        description='Aggregates Collection Case metrics and dispatches a Slack summary to #daily-collection-summary.'
        category='Collections Management'
    )
    public static List<SummaryOutput> executeDailySummary() {
        Integer totalCases = 0;
        Integer closedCases = 0;
        Integer pendingCases = 0;
        Integer escalatedCases = 0;

        if (Schema.sObjectType.Collection_Case__c.isAccessible()) {
            for (AggregateResult agg : [
                SELECT Case_Status__c status, COUNT(Id) caseCount
                FROM Collection_Case__c
                GROUP BY Case_Status__c
            ]) {
                String status = (String) agg.get('status');
                Integer countVal = (Integer) agg.get('caseCount');
                totalCases += countVal;

                if (status == 'Closed') {
                    closedCases += countVal;
                } else if (status == 'Escalated') {
                    escalatedCases += countVal;
                } else {
                    pendingCases += countVal;
                }
            }
        }

        SlackNotificationService.SlackNotificationRequest slackReq =
            SlackNotificationService.buildDailySummaryRequest(
                totalCases,
                closedCases,
                pendingCases,
                escalatedCases
            );

        SlackNotificationService.sendNotificationsFromFlow(
            new List<SlackNotificationService.SlackNotificationRequest>{ slackReq }
        );

        SummaryOutput output = new SummaryOutput();
        output.totalCases = totalCases;
        output.closedCases = closedCases;
        output.pendingCases = pendingCases;
        output.escalatedCases = escalatedCases;

        return new List<SummaryOutput>{ output };
    }
}

/**
 * @description       : Verifies zero outstanding balance on Loan_Account__c records,
 *                      transitions eligible loans to Closed, and closes associated
 *                      open Collection_Case__c records in bulk.
 * @group             : Collections Management
 */
public with sharing class LoanClosureService {

    public class LoanClosureException extends Exception {}

    /**
     * @description Invocable wrapper allowing Salesforce Flows (Loan_Auto_Closure)
     *              to invoke bulk-safe loan closure.
     * @param loanIds List of Loan_Account__c IDs from Flow
     */
    @InvocableMethod(
        label='Close Eligible Loans'
        description='Verifies zero outstanding balance, marks Loan Account Closed, and closes open Collection Cases.'
        category='Collections Management'
    )
    public static void closeEligibleLoansInvocable(List<Id> loanIds) {
        if (loanIds == null || loanIds.isEmpty()) {
            return;
        }
        closeEligibleLoans(new Set<Id>(loanIds));
    }

    /**
     * @description Closes Loan_Account__c records with Outstanding_Amount__c <= 0
     *              and closes any associated open Collection_Case__c records.
     * @param loanAccountIds Set of Loan_Account__c IDs to evaluate
     * @return Set<Id> IDs of loans that were closed
     */
    public static Set<Id> closeEligibleLoans(Set<Id> loanAccountIds) {
        Set<Id> closedLoanIds = new Set<Id>();
        if (loanAccountIds == null || loanAccountIds.isEmpty()) {
            return closedLoanIds;
        }

        if (!Schema.sObjectType.Loan_Account__c.isUpdateable() ||
            !Schema.sObjectType.Collection_Case__c.isUpdateable()) {
            throw new LoanClosureException('Insufficient permissions to close loans or collection cases.');
        }

        List<Loan_Account__c> loans = [
            SELECT Id, Outstanding_Amount__c, Loan_Status__c, Risk_Level__c
            FROM Loan_Account__c
            WHERE Id IN :loanAccountIds
            WITH SECURITY_ENFORCED
        ];

        List<Loan_Account__c> loansToClose = new List<Loan_Account__c>();
        for (Loan_Account__c loan : loans) {
            Decimal outstanding = loan.Outstanding_Amount__c != null ? loan.Outstanding_Amount__c : 0;
            if (outstanding <= 0 && loan.Loan_Status__c != 'Closed') {
                loan.Loan_Status__c = 'Closed';
                loan.Outstanding_Amount__c = 0;
                loan.Risk_Level__c = 'LOW';
                loansToClose.add(loan);
                closedLoanIds.add(loan.Id);
            }
        }

        if (!loansToClose.isEmpty()) {
            SObjectAccessDecision loanDecision = Security.stripInaccessible(AccessType.UPDATABLE, loansToClose);
            update loanDecision.getRecords();
        }

        // Also check cases for any loan in the input set that already has Outstanding_Amount__c == 0
        Set<Id> zeroBalanceLoanIds = new Set<Id>(closedLoanIds);
        for (Loan_Account__c loan : loans) {
            if (loan.Outstanding_Amount__c != null && loan.Outstanding_Amount__c <= 0) {
                zeroBalanceLoanIds.add(loan.Id);
            }
        }

        if (!zeroBalanceLoanIds.isEmpty()) {
            List<Collection_Case__c> openCases = [
                SELECT Id, Case_Status__c, Collection_Status__c, Loan_Account__c
                FROM Collection_Case__c
                WHERE Loan_Account__c IN :zeroBalanceLoanIds
                  AND Case_Status__c != 'Closed'
                WITH SECURITY_ENFORCED
            ];

            List<Collection_Case__c> casesToClose = new List<Collection_Case__c>();
            for (Collection_Case__c cCase : openCases) {
                cCase.Case_Status__c = 'Closed';
                cCase.Collection_Status__c = 'Recovered';
                casesToClose.add(cCase);
            }

            if (!casesToClose.isEmpty()) {
                SObjectAccessDecision caseDecision = Security.stripInaccessible(AccessType.UPDATABLE, casesToClose);
                update caseDecision.getRecords();
            }
        }

        return closedLoanIds;
    }
}

/**
 * @description       : Unit tests for LoanClosureService verifying zero-balance closure,
 *                      non-zero preservation, Invocable entry point, null inputs, and bulk closure.
 */
@isTest
private class LoanClosureServiceTest {

    @TestSetup
    static void setupData() {
        Customer__c cust = new Customer__c(
            Name = 'Lakshmi Narayanan',
            Phone_Number__c = '+919444012345',
            State__c = 'Tamil Nadu',
            Branch__c = 'Madurai'
        );
        insert cust;

        Loan_Account__c zeroLoan = new Loan_Account__c(
            Customer__c = cust.Id,
            Loan_Amount__c = 80000,
            Outstanding_Amount__c = 0,
            Amount_Paid__c = 80000,
            Due_Date__c = Date.today().addDays(-5),
            Loan_Status__c = 'Active',
            Risk_Level__c = 'MEDIUM'
        );

        Loan_Account__c openLoan = new Loan_Account__c(
            Customer__c = cust.Id,
            Loan_Amount__c = 80000,
            Outstanding_Amount__c = 25000,
            Amount_Paid__c = 55000,
            Due_Date__c = Date.today().addDays(-5),
            Loan_Status__c = 'Overdue',
            Risk_Level__c = 'MEDIUM'
        );

        insert new List<Loan_Account__c>{ zeroLoan, openLoan };

        insert new List<Collection_Case__c>{
            new Collection_Case__c(
                Customer__c = cust.Id,
                Loan_Account__c = zeroLoan.Id,
                Case_Status__c = 'In Progress',
                Priority__c = 'Medium',
                Collection_Status__c = 'Partial Payment'
            ),
            new Collection_Case__c(
                Customer__c = cust.Id,
                Loan_Account__c = openLoan.Id,
                Case_Status__c = 'In Progress',
                Priority__c = 'Medium',
                Collection_Status__c = 'Partial Payment'
            )
        };
    }

    @isTest
    static void testCloseEligibleLoansClosesOnlyZeroBalance() {
        List<Loan_Account__c> loans = [SELECT Id, Outstanding_Amount__c FROM Loan_Account__c];
        List<Id> allIds = new List<Id>();
        for (Loan_Account__c l : loans) {
            allIds.add(l.Id);
        }

        Test.startTest();
        LoanClosureService.closeEligibleLoansInvocable(allIds);
        Test.stopTest();

        Map<Id, Loan_Account__c> refreshed = new Map<Id, Loan_Account__c>([
            SELECT Id, Outstanding_Amount__c, Loan_Status__c, Risk_Level__c
            FROM Loan_Account__c
        ]);

        for (Loan_Account__c l : refreshed.values()) {
            if (l.Outstanding_Amount__c == 0) {
                System.assertEquals('Closed', l.Loan_Status__c, 'Zero balance loan must be Closed');
                System.assertEquals('LOW', l.Risk_Level__c, 'Closed loan risk must reset to LOW');
            } else {
                System.assertEquals('Overdue', l.Loan_Status__c, 'Non-zero loan must remain Overdue');
            }
        }

        List<Collection_Case__c> closedCases = [
            SELECT Id FROM Collection_Case__c WHERE Case_Status__c = 'Closed'
        ];
        System.assertEquals(1, closedCases.size(), 'Only the zero-balance loan case should be closed');
    }

    @isTest
    static void testNullAndEmptyInputs() {
        Test.startTest();
        Set<Id> resNull = LoanClosureService.closeEligibleLoans(null);
        Set<Id> resEmpty = LoanClosureService.closeEligibleLoans(new Set<Id>());
        LoanClosureService.closeEligibleLoansInvocable(null);
        LoanClosureService.closeEligibleLoansInvocable(new List<Id>());
        Test.stopTest();

        System.assertEquals(0, resNull.size(), 'Null input should return empty set');
        System.assertEquals(0, resEmpty.size(), 'Empty input should return empty set');
    }
}

/**
 * @description       : Lightning Web Component Apex Controller for customerLoanDetails.
 *                      Consolidates Customer, Loan Accounts, Collection Cases, and Risk Analysis
 *                      into a single payload so telecallers have zero tab switching.
 * @group             : Collections Management
 * @reference         : Reconstructed reference implementation for Srinidhi Associates
 */
public with sharing class LoanManagementController {

    /**
     * @description Consolidated DTO returned to the customerLoanDetails LWC.
     */
    public class CustomerLoanDashboardDTO {
        @AuraEnabled public CustomerSummary customer { get; set; }
        @AuraEnabled public List<LoanSummary> loans { get; set; }
        @AuraEnabled public List<CollectionCaseSummary> collectionCases { get; set; }
        @AuraEnabled public RiskAnalysisService.RiskAssessmentResult riskAssessment { get; set; }
        @AuraEnabled public Boolean hasLoans { get; set; }
        @AuraEnabled public Boolean hasCases { get; set; }

        public CustomerLoanDashboardDTO() {
            this.loans = new List<LoanSummary>();
            this.collectionCases = new List<CollectionCaseSummary>();
            this.hasLoans = false;
            this.hasCases = false;
        }
    }

    public class CustomerSummary {
        @AuraEnabled public Id id { get; set; }
        @AuraEnabled public String name { get; set; }
        @AuraEnabled public String phoneNumber { get; set; }
        @AuraEnabled public String email { get; set; }
        @AuraEnabled public String address { get; set; }
        @AuraEnabled public String state { get; set; }
        @AuraEnabled public String branch { get; set; }
        @AuraEnabled public String contactabilityStatus { get; set; }
    }

    public class LoanSummary {
        @AuraEnabled public Id id { get; set; }
        @AuraEnabled public String loanNumber { get; set; }
        @AuraEnabled public Decimal loanAmount { get; set; }
        @AuraEnabled public Decimal outstandingAmount { get; set; }
        @AuraEnabled public Decimal amountPaid { get; set; }
        @AuraEnabled public Decimal interestRate { get; set; }
        @AuraEnabled public Date dueDate { get; set; }
        @AuraEnabled public String loanStatus { get; set; }
        @AuraEnabled public String riskLevel { get; set; }
        @AuraEnabled public Decimal collectionEfficiency { get; set; }
        @AuraEnabled public Decimal daysOverdue { get; set; }
    }

    public class CollectionCaseSummary {
        @AuraEnabled public Id id { get; set; }
        @AuraEnabled public String caseNumber { get; set; }
        @AuraEnabled public Id loanAccountId { get; set; }
        @AuraEnabled public String loanNumber { get; set; }
        @AuraEnabled public String caseStatus { get; set; }
        @AuraEnabled public String priority { get; set; }
        @AuraEnabled public String assignedTelecallerName { get; set; }
        @AuraEnabled public String assignedFieldExecutiveName { get; set; }
        @AuraEnabled public Date nextFollowUpDate { get; set; }
        @AuraEnabled public String collectionStatus { get; set; }
        @AuraEnabled public String escalationReason { get; set; }
    }

    /**
     * @description Retrieves consolidated Customer, Loan Accounts, Collection Cases,
     *              and Risk Assessment for the specified Customer__c record.
     * @param customerId Id of the Customer__c record
     * @return CustomerLoanDashboardDTO consolidated data for the LWC
     */
    @AuraEnabled(cacheable=true)
    public static CustomerLoanDashboardDTO getCustomerLoanDashboard(Id customerId) {
        if (customerId == null) {
            throw new AuraHandledException('Customer record ID is required.');
        }

        if (!Schema.sObjectType.Customer__c.isAccessible() ||
            !Schema.sObjectType.Loan_Account__c.isAccessible() ||
            !Schema.sObjectType.Collection_Case__c.isAccessible()) {
            throw new AuraHandledException('Insufficient permissions to view customer collection records.');
        }

        try {
            List<Customer__c> customers = [
                SELECT Id, Name, Phone_Number__c, Email__c, Address__c,
                       State__c, Branch__c, Contactability_Status__c
                FROM Customer__c
                WHERE Id = :customerId
                WITH SECURITY_ENFORCED
                LIMIT 1
            ];

            if (customers.isEmpty()) {
                throw new AuraHandledException('Customer record not found.');
            }

            Customer__c customerRec = customers[0];
            CustomerLoanDashboardDTO dto = new CustomerLoanDashboardDTO();
            dto.customer = mapCustomer(customerRec);

            List<Loan_Account__c> loanRecords = [
                SELECT Id, Name, Customer__c, Loan_Amount__c, Outstanding_Amount__c,
                       Amount_Paid__c, Interest_Rate__c, Due_Date__c, Loan_Status__c,
                       Risk_Level__c, Collection_Efficiency__c, Days_Overdue__c
                FROM Loan_Account__c
                WHERE Customer__c = :customerId
                WITH SECURITY_ENFORCED
                ORDER BY Outstanding_Amount__c DESC, CreatedDate DESC
            ];

            for (Loan_Account__c loan : loanRecords) {
                dto.loans.add(mapLoan(loan));
            }
            dto.hasLoans = !dto.loans.isEmpty();

            List<Collection_Case__c> caseRecords = [
                SELECT Id, Name, Loan_Account__c, Loan_Account__r.Name, Case_Status__c,
                       Priority__c, Assigned_Telecaller__r.Name, Assigned_Field_Executive__r.Name,
                       Next_Follow_Up_Date__c, Collection_Status__c, Escalation_Reason__c
                FROM Collection_Case__c
                WHERE Customer__c = :customerId
                WITH SECURITY_ENFORCED
                ORDER BY CreatedDate DESC
            ];

            for (Collection_Case__c cCase : caseRecords) {
                dto.collectionCases.add(mapCase(cCase));
            }
            dto.hasCases = !dto.collectionCases.isEmpty();

            if (!loanRecords.isEmpty()) {
                dto.riskAssessment = RiskAnalysisService.analyzeLoanRisk(
                    loanRecords[0],
                    customerRec,
                    caseRecords.isEmpty() ? null : caseRecords[0]
                );
            }

            return dto;
        } catch (AuraHandledException ahe) {
            throw ahe;
        } catch (Exception ex) {
            throw new AuraHandledException('Unable to load customer loan details: ' + ex.getMessage());
        }
    }

    /**
     * @description Refreshes risk analysis for a specific Loan_Account__c record on demand.
     * @param loanAccountId Id of the Loan_Account__c record
     * @return RiskAnalysisService.RiskAssessmentResult
     */
    @AuraEnabled
    public static RiskAnalysisService.RiskAssessmentResult refreshLoanRiskAnalysis(Id loanAccountId) {
        if (loanAccountId == null) {
            throw new AuraHandledException('Loan Account ID is required.');
        }

        try {
            return RiskAnalysisService.evaluateAndPersistRisk(loanAccountId);
        } catch (Exception ex) {
            throw new AuraHandledException('Unable to refresh risk analysis: ' + ex.getMessage());
        }
    }

    private static CustomerSummary mapCustomer(Customer__c rec) {
        CustomerSummary summary = new CustomerSummary();
        summary.id = rec.Id;
        summary.name = rec.Name;
        summary.phoneNumber = rec.Phone_Number__c;
        summary.email = rec.Email__c;
        summary.address = rec.Address__c;
        summary.state = rec.State__c;
        summary.branch = rec.Branch__c;
        summary.contactabilityStatus = rec.Contactability_Status__c;
        return summary;
    }

    private static LoanSummary mapLoan(Loan_Account__c rec) {
        LoanSummary summary = new LoanSummary();
        summary.id = rec.Id;
        summary.loanNumber = rec.Name;
        summary.loanAmount = rec.Loan_Amount__c != null ? rec.Loan_Amount__c : 0;
        summary.outstandingAmount = rec.Outstanding_Amount__c != null ? rec.Outstanding_Amount__c : 0;
        summary.amountPaid = rec.Amount_Paid__c != null ? rec.Amount_Paid__c : 0;
        summary.interestRate = rec.Interest_Rate__c;
        summary.dueDate = rec.Due_Date__c;
        summary.loanStatus = rec.Loan_Status__c;
        summary.riskLevel = rec.Risk_Level__c;
        summary.collectionEfficiency = rec.Collection_Efficiency__c != null ? rec.Collection_Efficiency__c : 0;
        summary.daysOverdue = rec.Days_Overdue__c != null ? rec.Days_Overdue__c : 0;
        return summary;
    }

    private static CollectionCaseSummary mapCase(Collection_Case__c rec) {
        CollectionCaseSummary summary = new CollectionCaseSummary();
        summary.id = rec.Id;
        summary.caseNumber = rec.Name;
        summary.loanAccountId = rec.Loan_Account__c;
        summary.loanNumber = rec.Loan_Account__r != null ? rec.Loan_Account__r.Name : null;
        summary.caseStatus = rec.Case_Status__c;
        summary.priority = rec.Priority__c;
        summary.assignedTelecallerName = rec.Assigned_Telecaller__r != null ? rec.Assigned_Telecaller__r.Name : 'Unassigned';
        summary.assignedFieldExecutiveName = rec.Assigned_Field_Executive__r != null ? rec.Assigned_Field_Executive__r.Name : 'Unassigned';
        summary.nextFollowUpDate = rec.Next_Follow_Up_Date__c;
        summary.collectionStatus = rec.Collection_Status__c;
        summary.escalationReason = rec.Escalation_Reason__c;
        return summary;
    }
}

/**
 * @description       : Unit tests for LoanManagementController covering positive retrieval,
 *                      empty loan/case states, null input handling, and risk refresh.
 */
@isTest
private class LoanManagementControllerTest {

    @TestSetup
    static void setupData() {
        Customer__c cust = new Customer__c(
            Name = 'Rajesh Kumar',
            Phone_Number__c = '+919840012345',
            Email__c = 'rajesh.kumar@example.com',
            Address__c = '42 Anna Salai, Chennai',
            State__c = 'Tamil Nadu',
            Branch__c = 'Chennai Central',
            Contactability_Status__c = 'Contactable'
        );
        insert cust;

        Loan_Account__c loan = new Loan_Account__c(
            Customer__c = cust.Id,
            Loan_Amount__c = 500000,
            Outstanding_Amount__c = 350000,
            Amount_Paid__c = 150000,
            Interest_Rate__c = 12.5,
            Due_Date__c = Date.today().addDays(-45),
            Loan_Status__c = 'Overdue',
            Risk_Level__c = 'MEDIUM'
        );
        insert loan;

        Collection_Case__c cCase = new Collection_Case__c(
            Customer__c = cust.Id,
            Loan_Account__c = loan.Id,
            Assigned_Telecaller__c = UserInfo.getUserId(),
            Case_Status__c = 'In Progress',
            Priority__c = 'High',
            Next_Follow_Up_Date__c = Date.today().addDays(2),
            Collection_Status__c = 'Promise to Pay'
        );
        insert cCase;
    }

    @isTest
    static void testGetCustomerLoanDashboardPositive() {
        Customer__c cust = [SELECT Id FROM Customer__c LIMIT 1];

        Test.startTest();
        LoanManagementController.CustomerLoanDashboardDTO dto =
            LoanManagementController.getCustomerLoanDashboard(cust.Id);
        Test.stopTest();

        System.assertNotEquals(null, dto, 'Dashboard DTO should not be null');
        System.assertEquals('Rajesh Kumar', dto.customer.name, 'Customer name should match');
        System.assertEquals(true, dto.hasLoans, 'Customer should have loan accounts');
        System.assertEquals(1, dto.loans.size(), 'Should return one loan account');
        System.assertEquals(true, dto.hasCases, 'Customer should have collection cases');
        System.assertEquals(1, dto.collectionCases.size(), 'Should return one collection case');
        System.assertNotEquals(null, dto.riskAssessment, 'Risk assessment should be populated');
    }

    @isTest
    static void testGetCustomerLoanDashboardEmptyChildRecords() {
        Customer__c emptyCust = new Customer__c(
            Name = 'Priya Nair',
            Phone_Number__c = '+919840099999',
            State__c = 'Kerala',
            Branch__c = 'Kochi',
            Contactability_Status__c = 'Contactable'
        );
        insert emptyCust;

        Test.startTest();
        LoanManagementController.CustomerLoanDashboardDTO dto =
            LoanManagementController.getCustomerLoanDashboard(emptyCust.Id);
        Test.stopTest();

        System.assertEquals(false, dto.hasLoans, 'hasLoans should be false when no loans exist');
        System.assertEquals(false, dto.hasCases, 'hasCases should be false when no cases exist');
        System.assertEquals(null, dto.riskAssessment, 'Risk assessment should be null without loans');
    }

    @isTest
    static void testGetCustomerLoanDashboardNullInput() {
        Boolean exceptionThrown = false;
        Test.startTest();
        try {
            LoanManagementController.getCustomerLoanDashboard(null);
        } catch (AuraHandledException ex) {
            exceptionThrown = true;
        }
        Test.stopTest();

        System.assertEquals(true, exceptionThrown, 'Null customerId must throw AuraHandledException');
    }

    @isTest
    static void testRefreshLoanRiskAnalysisPositiveAndNull() {
        Loan_Account__c loan = [SELECT Id FROM Loan_Account__c LIMIT 1];

        Test.startTest();
        RiskAnalysisService.RiskAssessmentResult result =
            LoanManagementController.refreshLoanRiskAnalysis(loan.Id);
        Test.stopTest();

        System.assertNotEquals(null, result, 'Refreshed risk result should not be null');
        System.assertNotEquals(null, result.riskLevel, 'Risk level should be calculated');

        Boolean nullError = false;
        try {
            LoanManagementController.refreshLoanRiskAnalysis(null);
        } catch (AuraHandledException ex) {
            nullError = true;
        }
        System.assertEquals(true, nullError, 'Null loanAccountId must throw AuraHandledException');
    }
}

/**
 * @description       : Core business logic service for Loan_Account__c and Payment__c processing.
 *                      Handles bulk-safe payment validation, balance recalculation, and
 *                      delegates eligible zero-balance loans to LoanClosureService.
 * @group             : Collections Management
 */
public with sharing class LoanManagementService {

    public class LoanServiceException extends Exception {}

    /**
     * @description Processes a list of successful Payment__c records in bulk,
     *              updating Amount_Paid__c and Outstanding_Amount__c on parent Loan_Account__c records,
     *              and invoking LoanClosureService for loans that reach zero outstanding balance.
     * @param payments List of Payment__c records to process
     */
    public static void processSuccessfulPayments(List<Payment__c> payments) {
        if (payments == null || payments.isEmpty()) {
            return;
        }

        if (!Schema.sObjectType.Loan_Account__c.isUpdateable()) {
            throw new LoanServiceException('Insufficient permissions to update Loan Account balances.');
        }

        Map<Id, Decimal> paymentTotalsByLoanId = new Map<Id, Decimal>();
        for (Payment__c payment : payments) {
            if (payment == null || payment.Loan_Account__c == null) {
                continue;
            }
            if (payment.Payment_Status__c != 'Success') {
                continue;
            }
            if (payment.Payment_Amount__c == null || payment.Payment_Amount__c <= 0) {
                throw new LoanServiceException('Payment amount must be greater than zero.');
            }
            Decimal currentTotal = paymentTotalsByLoanId.containsKey(payment.Loan_Account__c)
                ? paymentTotalsByLoanId.get(payment.Loan_Account__c)
                : 0;
            paymentTotalsByLoanId.put(payment.Loan_Account__c, currentTotal + payment.Payment_Amount__c);
        }

        if (paymentTotalsByLoanId.isEmpty()) {
            return;
        }

        Map<Id, Loan_Account__c> loansById = new Map<Id, Loan_Account__c>([
            SELECT Id, Loan_Amount__c, Outstanding_Amount__c, Amount_Paid__c, Loan_Status__c
            FROM Loan_Account__c
            WHERE Id IN :paymentTotalsByLoanId.keySet()
            WITH SECURITY_ENFORCED
            FOR UPDATE
        ]);

        List<Loan_Account__c> loansToUpdate = new List<Loan_Account__c>();
        Set<Id> loansEligibleForClosure = new Set<Id>();

        for (Id loanId : paymentTotalsByLoanId.keySet()) {
            Loan_Account__c loan = loansById.get(loanId);
            if (loan == null) {
                continue;
            }

            Decimal paidIncrement = paymentTotalsByLoanId.get(loanId);
            Decimal existingPaid = loan.Amount_Paid__c != null ? loan.Amount_Paid__c : 0;
            Decimal existingOutstanding = loan.Outstanding_Amount__c != null
                ? loan.Outstanding_Amount__c
                : (loan.Loan_Amount__c != null ? loan.Loan_Amount__c : 0);

            if (paidIncrement > existingOutstanding) {
                throw new LoanServiceException(
                    'Payment amount (' + paidIncrement + ') exceeds current outstanding balance (' + existingOutstanding + ').'
                );
            }

            loan.Amount_Paid__c = existingPaid + paidIncrement;
            loan.Outstanding_Amount__c = Math.max(0, existingOutstanding - paidIncrement);
            loansToUpdate.add(loan);

            if (loan.Outstanding_Amount__c == 0) {
                loansEligibleForClosure.add(loan.Id);
            }
        }

        if (!loansToUpdate.isEmpty()) {
            SObjectAccessDecision decision = Security.stripInaccessible(AccessType.UPDATABLE, loansToUpdate);
            update decision.getRecords();
        }

        if (!loansEligibleForClosure.isEmpty()) {
            LoanClosureService.closeEligibleLoans(loansEligibleForClosure);
        }
    }

    /**
     * @description Recalculates exact Amount_Paid__c and Outstanding_Amount__c from all Success
     *              Payment__c records for the given Loan_Account__c IDs. Useful for batch reconciliation
     *              and payment reversals.
     * @param loanIds Set of Loan_Account__c IDs to recalculate
     */
    public static void recalculateLoanBalances(Set<Id> loanIds) {
        if (loanIds == null || loanIds.isEmpty()) {
            return;
        }

        if (!Schema.sObjectType.Loan_Account__c.isUpdateable() ||
            !Schema.sObjectType.Payment__c.isAccessible()) {
            throw new LoanServiceException('Insufficient permissions to recalculate loan balances.');
        }

        Map<Id, Decimal> totalSuccessPaymentsByLoan = new Map<Id, Decimal>();
        for (AggregateResult agg : [
            SELECT Loan_Account__c loanId, SUM(Payment_Amount__c) totalPaid
            FROM Payment__c
            WHERE Loan_Account__c IN :loanIds
              AND Payment_Status__c = 'Success'
            GROUP BY Loan_Account__c
        ]) {
            Id loanId = (Id) agg.get('loanId');
            Decimal totalPaid = (Decimal) agg.get('totalPaid');
            totalSuccessPaymentsByLoan.put(loanId, totalPaid != null ? totalPaid : 0);
        }

        List<Loan_Account__c> loans = [
            SELECT Id, Loan_Amount__c, Amount_Paid__c, Outstanding_Amount__c, Loan_Status__c
            FROM Loan_Account__c
            WHERE Id IN :loanIds
            WITH SECURITY_ENFORCED
        ];

        List<Loan_Account__c> loansToUpdate = new List<Loan_Account__c>();
        Set<Id> closureCandidates = new Set<Id>();

        for (Loan_Account__c loan : loans) {
            Decimal loanPrincipal = loan.Loan_Amount__c != null ? loan.Loan_Amount__c : 0;
            Decimal totalPaid = totalSuccessPaymentsByLoan.containsKey(loan.Id)
                ? totalSuccessPaymentsByLoan.get(loan.Id)
                : 0;
            Decimal remaining = Math.max(0, loanPrincipal - totalPaid);

            loan.Amount_Paid__c = totalPaid;
            loan.Outstanding_Amount__c = remaining;
            loansToUpdate.add(loan);

            if (remaining == 0 && loan.Loan_Status__c != 'Closed') {
                closureCandidates.add(loan.Id);
            }
        }

        if (!loansToUpdate.isEmpty()) {
            SObjectAccessDecision decision = Security.stripInaccessible(AccessType.UPDATABLE, loansToUpdate);
            update decision.getRecords();
        }

        if (!closureCandidates.isEmpty()) {
            LoanClosureService.closeEligibleLoans(closureCandidates);
        }
    }
}

